"""Independent Python reference: LPM model, spec image builder (randomized legal
layouts), and spec image validator. Used only for development testing."""
import random

BMP_NULL = 4194303
HOP_MAX = 4194302

def mask(addr, ln):
    if ln <= 0: return 0
    return (addr >> (128 - ln)) << (128 - ln)

def bits(addr, p, n):
    # MSB-first bits [p, p+n) of a 128-bit int; past-the-end reads zero
    v = 0
    for i in range(n):
        v <<= 1
        if p + i < 128:
            v |= (addr >> (127 - p - i)) & 1
    return v

def lpm(routes, addr):
    """routes: dict (len, masked_addr) -> hop"""
    for ln in range(128, -1, -1):
        k = (ln, mask(addr, ln))
        if k in routes:
            return routes[k]
    return None

class Node:
    def __init__(self, origin, depth, region):
        self.origin = origin
        self.depth = depth
        self.region = region      # int: first `depth` bits meaningful, rest 0
        self.type = None
        self.locals = []          # (addr,len,hop) for type 1..3
        self.kids = []            # (key, Node) sorted by key
        self.inl = []             # (addr,len,hop) for type 4/5
        self.stage = -1
        self.cell = 0
        self.slot = 0
        self.bm = 0
        self.ni = []
        self.bmid = -1
        self.nibase = 0
        self.bmp = BMP_NULL
        self.bulk = False

def decompose(prefixes, origin, depth, region):
    n = Node(origin, depth, region)
    if len(prefixes) == 1:
        n.type = 4
        n.inl = list(prefixes)
        return n
    if len(prefixes) == 2:
        n.type = 5
        n.inl = list(prefixes)
        return n
    groups = {}
    for (a, ln, hop) in prefixes:
        if ln < depth + 6:
            n.locals.append((a, ln, hop))
        else:
            groups.setdefault(bits(a, depth, 6), []).append((a, ln, hop))
    for k in sorted(groups):
        cr = region | (k << (128 - depth - 6))
        n.kids.append((k, decompose(groups[k], origin, depth + 6, cr)))
    c = len(n.kids)
    n.type = 1 if c <= 2 else (2 if c <= 6 else 3)
    return n

def height(n):
    h = 0
    for _, c in n.kids:
        h = max(h, height(c))
    return h + (1 if n.kids else 0)

def walk(n, out):
    out.append(n)
    for _, c in n.kids:
        walk(c, out)

def py_build(routes, rng):
    """routes: dict (len, masked_addr) -> hop. Randomized *legal* layout."""
    g0, g16, g64 = [], {}, {}
    for (ln, a), hop in routes.items():
        if ln <= 16: g0.append((a, ln, hop))
        elif ln <= 64: g16.setdefault(a >> 112, []).append((a, ln, hop))
        else: g64.setdefault(a >> 64, []).append((a, ln, hop))
    roots = []
    r16, r64 = [], {}
    if g0:
        roots.append(decompose(g0, 0, 0, 0))
    for k in sorted(g16):
        n = decompose(g16[k], 16, 16, k << 112)
        roots.append(n); r16.append((k, n))
    for k in sorted(g64):
        n = decompose(g64[k], 64, 64, k << 64)
        roots.append(n); r64[k] = n

    nodes = []
    for r in roots: walk(r, nodes)

    # TYPE3 direct/bulk split: at most three direct, the rest bulk (>= 4)
    for n in nodes:
        if n.type == 3:
            nd = rng.randint(0, 3)
            for j, (k, c) in enumerate(n.kids):
                c.bulk = j >= nd

    # randomized legal stage assignment (strictly decreasing along edges)
    def assign(n, max_stage):
        h = height(n)
        assert h <= max_stage, "unplaceable"
        n.stage = rng.randint(h, max_stage)
        # children
        if n.type == 3:
            bulk = [c for _, c in n.kids if c.bulk]
            direct = [c for _, c in n.kids if not c.bulk]
            hb = max([height(c) for c in bulk], default=0)
            bs = rng.randint(hb, n.stage - 1)
            for c in bulk: c.stage = bs
            for c in direct:
                hc = height(c)
                c.stage = rng.randint(hc, n.stage - 1)
        else:
            for _, c in n.kids:
                hc = height(c)
                c.stage = rng.randint(hc, n.stage - 1)
    for r in roots:
        assign(r, 10)

    # randomized dense slot allocation per stage
    by_stage = {s: [] for s in range(11)}
    for n in nodes:
        by_stage[n.stage].append(n)
    for s in range(11):
        items = []   # (kind, payload, cells)
        group_of = {}
        for n in by_stage[s]:
            if n.bulk:
                group_of.setdefault(id(n), None)
        # bulk groups: parents whose bulk children live in this stage
        consumed = set()
        for p in nodes:
            if p.type != 3: continue
            grp = [c for _, c in p.kids if c.bulk and c.stage == s]
            if grp:
                items.append(('bulk', grp, 2 * len(grp)))
                consumed.update(id(c) for c in grp)
        for n in by_stage[s]:
            if id(n) in consumed: continue
            if n.type in (2, 3, 5):
                items.append(('two', n, 2))
            else:
                items.append(('one', n, 1))
        total = sum(it[2] for it in items)
        for _attempt in range(200):
            order = items[:]
            rng.shuffle(order)
            pos = 0
            ok = True
            placed = []
            for it in order:
                size = it[2]
                if size % 2 == 1 and pos % 2 == 1:
                    # allowed only if it is a one-cell item (it is)
                    pass
                if size == 2 and pos % 2 == 1:
                    ok = False
                    break
                if size > 2 and pos % 2 == 1:
                    ok = False
                    break
                placed.append((it, pos))
                pos += size
            if ok and pos == total:
                break
        else:
            raise ValueError("no dense layout found")
        for it, pos in placed:
            if it[0] == 'bulk':
                for i, c in enumerate(it[1]):
                    c.cell = pos + 2 * i
                    c.slot = 2
            else:
                it[1].cell = pos
                it[1].slot = 1 if it[2] == 1 else 2

    # NI bitmaps/arrays in random node order
    order = nodes[:]
    rng.shuffle(order)
    ni = []
    pats = []
    for n in order:
        if n.type > 3: continue
        entries = []
        for (a, ln, hop) in n.locals:
            l = ln - n.depth
            v = bits(a, n.depth, l)
            entries.append(((1 << l) + v, hop))
        entries.sort()
        n.bm = 0
        n.nibase = 0 if not entries else len(ni)
        for pos, hop in entries:
            n.bm |= 1 << pos
            n.ni.append(hop)
        ni.extend(h for _, h in entries)
        pats.append(n.bm)
    pats = sorted(set(pats))
    for n in nodes:
        if n.type > 3: continue
        n.bmid = pats.index(n.bm)

    # BMP values via reference trie
    trie = {}
    def tins(a, ln, hop):
        cur = trie
        for i in range(ln):
            b = (a >> (127 - i)) & 1
            cur = cur.setdefault(b, {})
        if None in cur: raise ValueError("dup prefix")
        cur[None] = hop
    for n in nodes:
        if n.type <= 3:
            for (a, ln, hop) in n.locals: tins(a, ln, hop)
        else:
            for (a, ln, hop) in n.inl: tins(a, ln, hop)
    def tbmp(region, depth):
        cur = trie
        found = None in cur
        best = cur.get(None)
        for i in range(depth):
            b = (region >> (127 - i)) & 1
            if b not in cur: break
            cur = cur[b]
            if None in cur:
                found = True
                best = cur[None]
        return (found, best)
    for n in nodes:
        f, b = tbmp(n.region, n.depth)
        n.bmp = b if f else BMP_NULL

    # packing
    banks = {s: [] for s in range(11)}
    cells = {s: 0 for s in range(11)}
    for s in range(11):
        cells[s] = max([n.cell + n.slot for n in by_stage[s]], default=0)
        # dense check
        occ = [0] * cells[s]
        for n in by_stage[s]:
            for i in range(n.slot):
                occ[n.cell + i] += 1
        if cells[s] and (any(o != 1 for o in occ)):
            raise ValueError("layout not dense")
        rows = (cells[s] + 1) // 2
        banks[s] = [0] * rows

    def rec_bits(n):
        # returns list of (value, width) fields low->high, then reserved width
        f = []
        f.append((n.type, 3))
        f.append((n.bmp, 22))
        if n.type in (1, 2):
            f.append((n.bmid, 16))
            f.append((n.nibase, 22))
            slots = 2 if n.type == 1 else 6
            kids = list(n.kids)
            for j in range(slots):
                if j < len(kids):
                    k, c = kids[j]
                    f.append(((c.cell << 10) | ((c.stage & 0xF) << 6) | k, 32))
                else:
                    f.append((15 << 6, 32))
            f.append((0, 1))
        elif n.type == 3:
            f.append((n.bmid, 16))
            f.append((n.nibase, 22))
            bulk = [(k, c) for (k, c) in n.kids if c.bulk]
            direct = [(k, c) for (k, c) in n.kids if not c.bulk]
            bulkbm = 0
            for k, _ in bulk: bulkbm |= 1 << k
            f.append((bulkbm, 64))
            f.append((bulk[0][1].cell if bulk else 0, 22))
            f.append((bulk[0][1].stage if bulk else 0, 4))
            for j in range(3):
                if j < len(direct):
                    k, c = direct[j]
                    f.append(((c.cell << 10) | ((c.stage & 0xF) << 6) | k, 32))
                else:
                    f.append((15 << 6, 32))
            f.append((0, 7))
        else:
            for (a, ln, hop) in n.inl:
                if n.origin == 0:
                    frag, len8 = a & ((1 << 64) - 1), ln
                    frag &= ((1 << 64) - 1) >> (64 - ln) if ln < 64 else (1 << 64) - 1
                elif n.origin == 16:
                    len8 = ln - 16
                    frag = (a << 16) & ((1 << 64) - 1)
                else:
                    len8 = ln - 64
                    frag = a & ((1 << 64) - 1)
                f.append((frag, 64))
                f.append((len8, 8))
                f.append((hop, 22))
            f.append((0, 9 if n.type == 4 else 43))
        v, p = 0, 0
        for (x, w) in f:
            v |= (x & ((1 << w) - 1) if w < 64 else x) << p
            p += w
        return v

    for n in nodes:
        rec = rec_bits(n)
        if n.slot == 2:
            banks[n.stage][n.cell >> 1] |= rec
        else:
            off = (n.cell & 1) * 128
            banks[n.stage][n.cell >> 1] |= rec << off

    image = {
        'root': None,
        'front16': [],
        'front64': [],
        'cells': [cells[s] for s in range(11)],
        'banks': [[f'{w:064x}' for w in banks[s]] for s in range(11)],
        'bitmaps': [f'{p:016x}' for p in pats],
        'nexthops': list(ni),
    }
    if g0:
        image['root'] = [roots[0].stage, roots[0].cell]
    for k, n in r16:
        image['front16'].append([f'{k:04x}', n.stage, n.cell])
    for k in sorted(r64):
        n = r64[k]
        image['front64'].append([f'{k:016x}', n.stage, n.cell])
    return image
